import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/11-Computers-can-learn-by-themselves.html","title":"12-计算机也能上“自习”？","lang":"zh-CN","frontmatter":{"title":"12-计算机也能上“自习”？","icon":"read","date":"2025-04-15T08:25:09.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1744676936000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":11,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"70a42119e7a165e5f183d478adf4828e2dfe2395","time":1744676936000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"558cbf04c4cb5af8b6459ac9556eb77a353e4408","time":1744676762000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":7.45,"words":2235},"filePathRelative":"column/Programmingthinking/11-Computers-can-learn-by-themselves.md"}`),a={name:`11-Computers-can-learn-by-themselves.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>在学校里，有时候老师会让咱们上自习，有些地方还有专门的早自习课，让大家自己读书学习。</p><p>有意思的是，不光咱们人类会上自习，<strong>计算机也会“自习”</strong>。可计算机干吗要上“自习”呢？难不成它也要考试？这一讲，咱们就来说说计算机上“自习”是怎么回事。</p><p>我先给你布置一个小任务。现在，请你想象一下，自己面前有一台冰箱。然后，请你打开冰箱门，把里面的东西做一个<strong>分类</strong>。诶，这个任务，很简单吧？</p><p>你可以轻轻松松把冰箱里的<strong>水果</strong>、<strong>蔬菜</strong>、<strong>肉类</strong>还有<strong>饮料</strong>什么的分开。而且，你甚至不知不觉就会把蔬菜里带叶的与不带叶的分开，把水果里酸的和甜的给分开。</p><figure><img src="/assets/378bd4a2efd89c464f9083f7002622aa-7tGicZdn.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这件事不光你做起来简单，让计算机来做也不难。咱们前面说过了，可以通过不停地让计算机看图片，教它们认识各种各样的东西。所以，对现有的水果蔬菜做分类，这个问题对咱们人类和计算机来说，都不难。</p><p>好，那接下来，咱们换一个场景。假如现在，你是一位宇航员，<strong>要去一颗全新的星球上考察</strong>。下了飞船一看，你直接叫了一声“好家伙”。这星球上已经有许许多多的生物了。不过，这些生物和地球上的生物完全不一样。</p><p>这里的树上也结满了各种各样的果子，都是地球上完全没见过的，有<strong>三角形的、五角星形的，还有正方形</strong>的。颜色呢？也是奇奇怪怪的，蓝色、绿色、橙色、粉色的都有。</p><figure><img src="/assets/bc63fe7e1025b07d4dd4cfc1ae0478cf-BbEkAvPO.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这时候，通讯器里突然传来了命令，让你把这些果子做个分类，如果是你的话，会怎么办呢？</p><p>我相信，虽然你并不知道这些果子叫什么名字，但你一定能完成任务。因为，这是咱们从幼儿园开始就接受的训练啊。</p><p>如果你还记得的话，应该能想起来，当时自己经常会碰到一类题，让你给各种各样的东西分类。很多时候，即使咱们不知道被分类的到底是什么东西，但还是可以<strong>按照颜色或者是形状</strong>，把它们都分清楚。</p><p>同样的，咱们现在虽然不知道这些果子到底叫什么名字，但是也可以按照形状来分，三角形的一类、五角星形的一类、正方形的一类。咱们还可以按照颜色来分类，红色的一类、蓝色的一类，如此等等。当然了，这样的分类方法并不完美，但在什么都不知道的情况下，也算是个不错的办法了。</p><p>在这里我要给你说明一下。前面咱们在给冰箱里的东西做分类的时候，咱们<strong>明确知道</strong>每个东西是啥，属于哪一类，这种情况咱们叫分类是没问题的。</p><p>但是在外星球上，咱们<strong>完全不知道</strong>要分类的东西是什么，也没有一个确切的分类标准，先按颜色分还是先按形状分好像都可以。这种情况，咱们一般是不叫分类的，而是叫<strong>聚类</strong>。聚类的意思，就是根据一些特征把不同的东西聚在一块。</p><figure><img src="/assets/a5f52d948b3247e16b30c50b42452d7f-Bs9vqRv0.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>科学家让计算机给东西做聚类的时候，往往就要让计算机上“自习”了，因为咱们自己都没法给出一个明确的标准对吧？当然就没法直接教它了。</p><p>那计算机是怎么自习的呢？其实，它自习的过程和你按照形状、颜色做聚类的方法特别像。举个例子。</p><p>首先，咱们前面说了，计算机要处理这些果子必须先对它们进行<strong>抽象</strong>，比如，假如果子是<strong>红色</strong>的，计算机就给果子打上颜色标签<strong>1</strong>，<strong>蓝色</strong>就给标签<strong>2</strong>，如果<strong>红色有一点点偏蓝</strong>呢，那就认为它是<strong>1.2</strong>好了。</p><p>同样的，如果果子是三角形的，就在形状这个标签上给它记成数字1，五角星形的记成2，看起来像三角形但稍微又多出两个小角呢，就记成1.4。</p><p>总之，就是把所有果子的形状和颜色都变成一组组数字，这样一来，计算机就可以开始处理这堆数字了。最后，计算机也是把颜色和形状比较类似的水果放在一块，把它们聚为一类。</p><p>可是，这和“自习”有什么关系呢？</p><p>你应该还记得吧，咱们前面说计算机学习辨认图片上的小猫小狗的时候，是有人类告诉它们判断得对不对的。这种有人看着的学习方法有个特别形象的名字，叫<strong>监督学习</strong>，在人类的监督之下学习。</p><figure><img src="/assets/e47c246f1b06e7abade3ea15078d8565-BZzKeHg0.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>但现在情况不一样了，人类自己都不知道该怎么分类，自然也就没法监督了，一切都要靠计算机自己判断。怎么判断呢？</p><p>计算机每看到一个新的果子，都会把新果子的参数加入原来的<strong>数据库</strong>里面，随着新果子数量越来越多，判断标准可能会发生改变。</p><p>比如原来四四方方的果子可能会和三角形的果子归为一类。可随着观察的果子多了，计算机就发现，四四方方的果子还挺常见的，应该单独归为一类。</p><figure><img src="/assets/44f35b56f6db44a3abbb201e31314897-CYs_DBAB.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>到底哪些果子要归为一类，这个判断标准不是人类给它设定好的，也不是它自己瞎猜出来的，而是<strong>根据收集到的果子的参数不断调整出来的</strong>。</p><p>这种没有人类帮忙做判断，计算机自己根据实际情况自己学习的方式，就叫做无监督学习。</p><p>这里有一种思想特别值得你学习，那就是“根据实际情况不断优化调整，以达到最佳效果”。</p><p>我给你举个例子吧，我们在生活中可能也会定各种各样的计划。比如快考试了，你可能计划每天晚上都看半小时语文、半小时数学、半小时英语。</p><p>结果呢，过了三天之后你发现，英语已经掌握得差不多了，语文学得还不太好，那就可以把复习英语的时间挪20分钟给语文。再过几天，又发现数学落下了，于是又可以少看20分钟语文，多看20分钟的数学。</p><p>虽然和咱们开始定的计划不太一样，但不断<strong>根据实际情况调整自己的计划策略</strong>，才能达到最好的效果。</p><p>咱们还是说回这个无监督学习。无监督学习在实际生活中能有什么用处吗？用处可大了。</p><p>如果将来有一天，我们真的要<strong>探索一颗完全未知的星球</strong>，可能就得让计算机帮咱们对星球上的东西做聚类。另外，虽然咱们人类现在还没有派出星际科考队，但是在地球上，也有很多我们不太了解的东西需要做分类。</p><p>比方说吧，有些微生物，也就是像细菌这样肉眼看不见的小生物，人们就不是特别了解，如果一上来就让人类科学家去分析，可能会浪费大量的时间。</p><p>这时候，计算机的无监督学习就派上用场了。咱们可以先让计算机自己学一会儿，替咱们<strong>总结一个初步的规律</strong>，然后再在这个基础上做深入的研究，这样就可以节省不少时间和精力了。你也可以畅想一下，无监督学习还能帮你干什么呢？在留言区里写下来吧。</p><p>那现在，咱们知道了，计算机不光可以在人类的指导下学习，还可以自习，那会不会有一天，机器人会产生和人类一样的智慧呢？你还别说，还真有科学家研究过这个问题，而且还提出了测试计算机有没有智慧的方法，到底是什么方法呢？我们下集再说。</p>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};